#include <iostream>
#include <string>
class MyStream {
private:
  std::string buffer;
  bool is_open;
public:
  MyStream() : buffer(""), is_open(false) {}
  MyStream(const MyStream&) = delete; // Prevent copying
  MyStream& operator=(const MyStream&) = delete;
  MyStream(MyStream&& rhs) noexcept : buffer(std::move(rhs.buffer)), is_open(rhs.is_open) {
    rhs.is_open = false; // Important: Resource transfer
  }
  MyStream& operator=(MyStream&& rhs) noexcept {
    if (this != &rhs) {
      buffer = std::move(rhs.buffer);
      is_open = rhs.is_open;
      rhs.is_open = false;
    }
    return *this;
  }
  void swap(MyStream& other) noexcept {
    std::swap(buffer, other.buffer);
    std::swap(is_open, other.is_open);
  }
  // ... other stream methods ...
};
template <typename T> 
MyStream& operator<<(MyStream& stream, const T& value) {
  stream.buffer += std::to_string(value);
  return stream; 
}
int main() {
  MyStream stream1;
  stream1 << 10 << " Hello";
  MyStream stream2 = std::move(stream1); // Move constructor used
  std::cout << stream2.buffer << std::endl; // Output: 10 Hello
  return 0;
}
